contract InvMutTest is Test {
    C c;
    address immutable deployer = address(this);

    function setUp() public {
        c = new C();
    }

    function testFuzz_property(bytes calldata _data) public {
        vm.assume(_data.length >= 20);
        bytes memory maliciousData = abi.encodePacked(
            bytes32(uint256(uint160(address(this)))),
            _data
        );
        Attacker attacker = new Attacker();
