    // storage layout: slot 0 is overwritten with msg.sender (address of InvMutTest) when delegatecalled
    address public slot0;
    fallback() external payable {
        // any call executes this: overwrite slot 0 with caller's address
        slot0 = msg.sender;
    }
}

